<link rel="stylesheet" type="text/css" href="style.css">
<?php

$apiKey = "f1b704855b12a14273b7c6aee85ce012";
$city = urlencode("Catanduva");
$units = "metric";
$url = "https://api.openweathermap.org/data/2.5/weather?q={$city}&units={$units}&appid={$apiKey}&lang=pt_br";
$response = file_get_contents($url);

// Verificando se houve erro na requisição
if ($response === FALSE) {
    die("Erro ao acessar a API.");
}

// Convertendo a resposta para JSON
$data = json_decode($response, true);

// Exibindo os dados
echo "<div class='container'><div class='box21'><b>Cidade: </b>" . $data['name'] . "<br>";
echo "<b>Temperatura: </b>" . $data['main']['temp'] . "°C<br>";
echo "<b>Condição: </b>" . $data['weather'][0]['description'] . "<br>";
echo "<b>Umidade: </b>" . $data['main']['humidity'] . "%<br>";
echo "<b>Velocidade do Vento: </b>" . $data['wind']['speed'] . " m/s<br></div>";
?>

<div class="box2">
<img id="Icone" src="data:image/png;base64," alt="Ícone do tempo">
</div>
</div>
<script>
    var weatherData = <?php echo json_encode($data); ?>;    
    window.onload = function() {
        atualizaIcone(weatherData.weather[0].description);
    };

    async function atualizaIcone(condicao) {
        let icone = document.getElementById("Icone");

        if (condicao === "chuva" || condicao === "chuva moderada" || condicao === "trovoada com chuva fraca") {
            icone.src = "data:image/png;base64,";
        } else if (condicao === "nublado") {
            icone.src = "data:image/png;base64,";
        } else {
            icone.src = "data:image/png;base64,";
        } 
    }
</script>